import cocotb
from cocotb.clock import Clock
from cocotb.triggers import RisingEdge, FallingEdge, Timer

# Generated by Nishkam Studio from the scan chain and Quaigh patterns (issue #10, early, not validated).
# Chain order: DFF_0.Q, DFF_1.Q, DFF_2.Q (first flop after scan_in). 6 patterns.
@cocotb.test()
async def scan_chain_patterns(dut):
    cocotb.start_soon(Clock(dut.CK, 10, units="ns").start())
    dut.scan_in.value = 0
    # pattern 1 of 6
    dut.scan_en.value = 1
    await FallingEdge(dut.CK)
    dut.scan_in.value = 0
    await RisingEdge(dut.CK)
    await FallingEdge(dut.CK)
    dut.scan_in.value = 0
    await RisingEdge(dut.CK)
    await FallingEdge(dut.CK)
    dut.scan_in.value = 0
    await RisingEdge(dut.CK)
    await FallingEdge(dut.CK)
    dut.scan_en.value = 0
    dut.G0.value = 0
    dut.G1.value = 1
    dut.G2.value = 1
    dut.G3.value = 1
    await Timer(1, units="ns")
    assert int(dut.G17.value) == 1, "pattern 1: output G17 is wrong"
    await RisingEdge(dut.CK)
    dut.scan_en.value = 1
    await FallingEdge(dut.CK)
    assert int(dut.scan_out.value) == 0, "pattern 1: captured flop 2 is wrong"
    await RisingEdge(dut.CK)
    await FallingEdge(dut.CK)
    assert int(dut.scan_out.value) == 0, "pattern 1: captured flop 1 is wrong"
    await RisingEdge(dut.CK)
    await FallingEdge(dut.CK)
    assert int(dut.scan_out.value) == 0, "pattern 1: captured flop 0 is wrong"
    await RisingEdge(dut.CK)

    # pattern 2 of 6
    dut.scan_en.value = 1
    await FallingEdge(dut.CK)
    dut.scan_in.value = 0
    await RisingEdge(dut.CK)
    await FallingEdge(dut.CK)
