    await FallingEdge(dut.CK)
    assert int(dut.scan_out.value) == 1, "pattern 2: captured flop 1 is wrong"
    await RisingEdge(dut.CK)
    await FallingEdge(dut.CK)
    assert int(dut.scan_out.value) == 0, "pattern 2: captured flop 0 is wrong"
